\frac{x}{1+x^{2}}+\frac{y}{1+y^{2}}+\frac{z}{1+z^{2}} & =\frac{x}{(x+y)(x+z)}+\frac{y}{(y+x)(y+z)}+\frac{z}{(z+x)(z+y)} \\
& =\frac{x(y+z)+y(x+z)+z(x+y)}{(x+y)(y+z)(z+x)} \\
& =\frac{2}{(x+y)(y+z)(z+x)} \tag{1}
\end{align*}
$$

It is easy to show that
$$
\begin{equation*}
(x+y)(y+z)(z+x)=x+y+z-x y z \tag{2}
\end{equation*}
$$

Due to the well-known inequality $(x+y+z)^{2} \geq 3(x y+y z+z x)$ we obtain
$$
\begin{equation*}
(x+y+z)^{2} \geq 3(x y+y z+z x)=3, \text { i.e. } \quad x+y+z \geq \sqrt{3} \tag{3}
