& \frac{1}{9}\left(\frac{1}{a+c}+\frac{1}{b+c}+\frac{1}{c+d}\right) \geq \frac{1}{a+b+3 c+d} \\
& \frac{1}{9}\left(\frac{1}{a+d}+\frac{1}{b+d}+\frac{1}{c+d}\right) \geq \frac{1}{a+b+c+3 d}
