\frac{a^{2}}{b}+\frac{b^{2}}{c}+\frac{c^{2}}{a}=\frac{a^{2}-a b+b^{2}}{b}+\frac{b^{2}-b c+c^{2}}{c}+\frac{c^{2}-c a+a^{2}}{a} \tag{1}
\end{equation*}
$$

Since for any $x, y \in \mathbb{R}$, we have $x^{2}-x y+y^{2} \geq x y$, by (1) we get
$$
\frac{a^{2}}{b}+\frac{b^{2}}{c}+\frac{c^{2}}{a} \geq \frac{a b}{b}+\frac{b c}{c}+\frac{c a}{a}=a+b+c
$$ Therefore, the answer is (B) $\geq$.

Since $a b c d=1$, there are two numbers $x, y$ among $a, b, c, d$, such that $x, y \geq 1$ or $x, y \leq 1$. Without loss of generality we may suppose that they are $b$ and $d$. Then clearly $(b-1)(d-1) \geq 0$, i.e. $b d+1 \geq b+d$.

According to the Cauchy-Schwarz inequality and the previous note, we obtain
$$
\begin{aligned}
\left(1+a^{2}\right)\left(1+b^{2}\right)\left(1+c^{2}\right)\left(1+d^{2}\right) & =\left(1+a^{2}+b^{2}+a^{2} b^{2}\right)\left(c^{2}+1+d^{2}+c^{2} d^{2}\right) \\
& \geq(c+a+b d+1)^{2} \geq(a+b+c+d)^{2}
\end{aligned}
$$

Equality holds iff $a=b=c=d=1$. Therefore, the answer is (B) $\geq$.

Applying the Cauchy-Schwarz inequality we get
$$
\begin{equation*}
a \sqrt{b+c}+b \sqrt{c+a}+c \sqrt{a+b} \leq \sqrt{2\left(a^{2}+b^{2}+c^{2}\right)(a+b+c)} \tag{1}
\end{equation*}
$$

Using Chebishev's inequality we get
$$
\begin{equation*}
\sqrt{2\left(a^{2}+b^{2}+c^{2}\right)(a+b+c)} \leq \sqrt{6\left(a^{3}+b^{3}+c^{3}\right)} \tag{2}
\end{equation*}
$$

Also from $A M \geq G M$ we have
$$
\begin{equation*}
a^{3}+b^{3}+c^{3} \geq 3 a b c=6 \tag{3}
\end{equation*}
$$

Combining (1), (2) and (3) we have
$$
a^{3}+b^{3}+c^{3} \geq \sqrt{6\left(a^{3}+b^{3}+c^{3}\right)} \geq a \sqrt{b+c}+b \sqrt{c+a}+c \sqrt{a+b}
$$

Equality holds iff $a=b=c=\sqrt[3]{2}$. Therefore, the answer is (B) $\geq$.

We have
$$
2 s=a+b+c \geq 3 \sqrt[3]{a b c}=3 \sqrt[3]{4 P R}=3 \sqrt[3]{4 s r R} \geq 3 \sqrt[3]{8 s r^{2}}
$$
i.e.
$$
s \geq 3 \sqrt[3]{s r^{2}}
$$
or
$$
s \geq 3 r \sqrt{3}
$$

Equality occurs if and only if $a=b=c$.2 We have
$$
\begin{equation*}
\frac{s}{3}=\frac{(s-a)+(s-b)+(s-c)}{3} \stackrel{A M \geq G M}{\geq} \sqrt[3]{(s-a)(s-b)(s-c)} \tag{1}
\end{equation*}
$$

Also
$$
\begin{equation*}
(s-a)(s-b)(s-c)=\frac{P^{2}}{s}=\frac{s^{2} r^{2}}{s}=s r^{2} \tag{2}
\end{equation*}
$$

By (1) and (2) we obtain
$$
s \geq 3 \sqrt[3]{s r^{2}}, \quad \text { i.e. } \quad s \geq 3 \sqrt{3} r
$$

Equality occurs if and only if $a=b=c$. Therefore, the answer is (B) $\geq$.

By the power mean inequality we have that
$$
\begin{aligned}
& M_{2}(a, b, c) \leq M_{3}(a, b, c) \\
& \quad \Leftrightarrow \quad \sqrt{\frac{a^{2}+b^{2}+c^{2}}{3}} \leq \sqrt[3]{\frac{a^{3}+b^{3}+c^{3}}{3}} \\
& \quad \Leftrightarrow \quad\left(a^{2}+b^{2}+c^{2}\right)^{3} \leq 3\left(a^{3}+b^{3}+c^{3}\right)^{2}
\end{aligned}
$$ Therefore, the answer is (A) $\leq$.

For any real number $x$, the numbers $x-1, x^{2}-1, x^{3}-1$ and $x^{4}-1$, are of the same sign.

Therefore
$$
(x-1)\left(x^{3}-1\right) \geq 0, \quad\left(x^{2}-1\right)\left(x^{3}-1\right) \geq 0 \quad \text { and } \quad\left(x^{3}-1\right)\left(x^{4}-1\right) \geq 0
$$
i.e.
$$
\begin{array}{r}
c^{4}-c^{3}-c+1 \geq 0 \tag{1}
\end{array}
$$
$$
\begin{array}{r}
b^{5}-b^{3}-b^{2}+1 \geq 0 \tag{2}
\end{array}
$$
$$
\begin{array}{r}
a^{7}-a^{4}-a^{3}+1 \geq 0 \tag{3}
\end{array}
$$

By (1), (2) and (3) we have
$$
a^{7}-a^{4}+3 \geq a^{3}+2, \quad b^{5}-b^{2}+3 \geq b^{3}+2 \quad \text { and } \quad c^{4}-c+3 \geq c^{3}+2
$$

After multiplying these inequalities it follows that
$$
\begin{equation*}
\left(a^{7}-a^{4}+3\right)\left(b^{5}-b^{2}+3\right)\left(c^{4}-c+3\right) \geq\left(a^{3}+2\right)\left(b^{3}+2\right)\left(c^{3}+2\right) \tag{4}
\end{equation*}
$$

Analogously as in Problem 126, we can prove that
$$
\begin{equation*}
\left(a^{3}+2\right)\left(b^{3}+2\right)\left(c^{3}+2\right) \geq(a+b+c)^{3} \tag{5}
\end{equation*}
$$

By the obvious inequality $(a+b+c)^{2} \geq 3(a b+b c+c a)$, since $a b+b c+c a=3$ we deduce that
$$
\begin{equation*}
a+b+c \geq 3 \tag{6}
\end{equation*}
$$

Finally from (4), (5) and (6) we obtain the required inequality.
Equality occurs iff $a=b=c=1$. Therefore, the answer is (B) $\geq$.

theorems.Theorem:
Let $a_{i} \in(0, \infty), i=1,2, \ldots, n$, and $\alpha_{i} \in[0,1], i=1,2, \ldots, n$, be such that $\alpha_{1}+\alpha_{2}+\cdots+\alpha_{n}=1$.
Then
$$
\begin{equation*}
a_{1}^{\alpha_{1}} a_{2}^{\alpha_{2}} \cdots a_{n}^{\alpha_{n}} \leq a_{1} \alpha_{1}+a_{2} \alpha_{2}+\cdots+a_{n} \alpha_{n} \tag{7.9}
\end{equation*}
$$

Let $f:(a, b) \rightarrow \mathbb{R}$ be a convex function on the interval $(a, b)$. Let $n \in \mathbb{N}$ and $\alpha_{1}, \alpha_{2}, \ldots, \alpha_{n} \in(0,1)$ be real numbers such that $\alpha_{1}+\alpha_{2}+\cdots+\alpha_{n}=1$. Then for any $x_{1}, x_{2}, \ldots, x_{n} \in(a, b)$ we have
$$
f\left(\sum_{i=1}^{n} \alpha_{i} x_{i}\right) \leq \sum_{i=1}^{n} \alpha_{i} f\left(x_{i}\right)
$$
i.e.
$$
\begin{equation*}
f\left(\alpha_{1} x_{1}+\alpha_{2} x_{2}+\cdots+\alpha_{n} x_{n}\right) \leq \alpha_{1} f\left(x_{1}\right)+\alpha_{2} f\left(x_{2}\right)+\cdots+\alpha_{n} f\left(x_{n}\right) \tag{7.2}
\end{equation*}
$$

solution:
Let $p=a+b+c, q=a b+b c+c a, r=a b c$.

Since $\frac{1}{a+1}+\frac{1}{b+1}+\frac{1}{c+1}=2$ we have
$$
\begin{equation*}
(a+1)(b+1)+(b+1)(c+1)+(c+1)(a+1)=2(a+1)(b+1)(c+1) \tag{1}
\end{equation*}
$$

Using the identities $I_{9}$ and $I_{10}$, identity (1) becomes $3+2 p+q=2(1+p+$ $q+r$ ), from which it follows that
$$
\begin{equation*}
q+2 r=1 \tag{2}
\end{equation*}
$$

It can easily be shown that
$(8 a b+1)(8 b c+1)+(8 b c+1)(8 c a+1)+(8 c a+1)(8 a b+1)=64 p r+16 q+3$ and
$$
(8 a b+1)(8 b c+1)(8 c a+1)=512 r^{2}+64 p r+8 q+1
$$

We need to prove that
$$
64 p r+16 q+3 \geq 512 r^{2}+64 p r+8 q+1
$$
which is equivalent to
$$
\begin{equation*}
8 q+2 \geq 512 r^{2} \tag{3}
\end{equation*}
$$

By $q^{3} \geq 27 r^{2}$ and since $q=1-2 r$ we obtain
$$
\begin{aligned}
& (1-2 r)^{3} \geq 27 r^{2} \\
& \quad \Leftrightarrow \quad 8 r^{3}+15 r^{2}+6 r-1 \leq 0 \\
& \quad \Leftrightarrow \quad(8 r-1)\left(r^{2}+2 r+1\right) \leq 0
\end{aligned}
$$

Thus
$$
\begin{equation*}
8 r-1 \leq 0, \quad \text { i.e. } \quad r \leq \frac{1}{8} \tag{4}
\end{equation*}
$$

Now since $q+2 r=1$, inequality (3) becomes
$$
\begin{aligned}
& 8(1-2 r)+2 \geq 512 r^{2} \\
& \quad \Leftrightarrow \quad 512 r^{2}+16 r-10 \leq 0 \\
& \quad \Leftrightarrow \quad(8 r-1)(64 r+10) \leq 0
\end{aligned}
$$
which follows due to (4). Therefore, the answer is (B) $\geq$.

theorems.Theorem:
For any real numbers $a_{1}, a_{2}, \ldots, a_{n}$ and $b_{1}, b_{2}, \ldots, b_{n}$

$$
\begin{gathered}
\left(a_{1}^{2}+a_{2}^{2}+\ldots+a_{n}^{2}\right)\left(b_{1}^{2}+b_{2}^{2}+\ldots+b_{n}^{2}\right) \geq \\
\geq\left(a_{1} b_{1}+a_{2} b_{2}+\ldots+a_{n} b_{n}\right)^{2}
\end{gathered}
$$

with equality if and only if $a_{i}$ and $b_{i}$ are proportional, $i=1,2, \ldots, n$.

solution:
The given inequality is equivalent to
$$
\begin{aligned}
& \frac{1}{8 a b c}-\frac{1}{8 a b c+(a+b-c)^{3}}+\frac{1}{8 a b c}-\frac{1}{8 a b c+(b+c-a)^{3}}+\frac{1}{8 a b c} \\
& \quad-\frac{1}{8 a b c+(c+a-b)^{3}} \\
& \quad \geq \frac{3}{8 a b c}-\frac{1}{3 a b c}
\end{aligned}
$$
i.e.
$$
\begin{equation*}
\frac{(a+b-c)^{3}}{8 a b c+(a+b-c)^{3}}+\frac{(b+c-a)^{3}}{8 a b c+(b+c-a)^{3}}+\frac{(c+a-b)^{3}}{8 a b c+(c+a-b)^{3}} \geq \frac{1}{3} \tag{1}
\end{equation*}
$$

Lemma 21.3 Let $a, b, c, x, y, z \in \mathbb{R}^{+}$. Then
$$
\frac{a^{3}}{x}+\frac{b^{3}}{y}+\frac{c^{3}}{z} \geq \frac{(a+b+c)^{3}}{3(x+y+z)}
$$

Proof We'll use the generalized Hölder inequality, i.e.
If $\left(a_{i}\right),\left(b_{i}\right),\left(c_{i}\right), i=1,2, \ldots, n$, are positive real numbers and $p, q, r$ are such that $p+q+r=1$, then
$$
\left(\sum_{i=1}^{n} a_{i}\right)^{p} \cdot\left(\sum_{i=1}^{n} b_{i}\right)^{q} \cdot\left(\sum_{i=1}^{n} c_{i}\right)^{r} \geq \sum_{i=1}^{n} a_{i}^{p} b_{i}^{q} c_{i}^{r}
$$

For $n=3, p=q=r=1 / 3$ and
$$
\begin{aligned}
& a_{1}=a_{2}=a_{3}=1 ; \quad b_{1}=x, \quad b_{2}=y, \quad b_{3}=z \\
& c_{1}=\frac{a^{3}}{x}, \quad c_{2}=\frac{b^{3}}{y}, \quad c_{3}=\frac{c^{3}}{z}
\end{aligned}
$$
we get
$$
\begin{gathered}
\sqrt[3]{(1+1+1)(x+y+z)\left(\frac{a^{3}}{x}+\frac{b^{3}}{y}+\frac{c^{3}}{z}\right)} \\
\geq \sqrt[3]{1 \cdot x \cdot \frac{a^{3}}{x}}+\sqrt[3]{1 \cdot y \cdot \frac{b^{3}}{y}}+\sqrt[3]{1 \cdot z \cdot \frac{c^{3}}{z}}
\end{gathered}
$$
i.e.
$3(x+y+z)\left(\frac{a^{3}}{x}+\frac{b^{3}}{y}+\frac{c^{3}}{z}\right) \geq(a+b+c)^{3} \quad \Leftrightarrow \quad \frac{a^{3}}{x}+\frac{b^{3}}{y}+\frac{c^{3}}{z} \geq \frac{(a+b+c)^{3}}{3(x+y+z)}$.
According to (1) and Lemma 21.3, we have
$$
\begin{gathered}
\frac{(a+b-c)^{3}}{8 a b c+(a+b-c)^{3}}+\frac{(b+c-a)^{3}}{8 a b c+(b+c-a)^{3}}+\frac{(c+a-b)^{3}}{8 a b c+(c+a-b)^{3}} \\
\geq \frac{(a+b-c+b+c-a+c+a-b)^{3}}{3\left(24 a b c+(a+b-c)^{3}+(b+c-a)^{3}+(c+a-b)^{3}\right)}=\frac{1}{3}
\end{gathered}
$$ Therefore, the answer is (A) $\leq$.

We have
$$
\begin{equation*}
a^{2}+b^{2}+\frac{1}{a^{2}}+\frac{b}{a}=\left(b+\frac{1}{2 a}\right)^{2}+a^{2}+\frac{3}{4 a^{2}} \tag{1}
\end{equation*}
$$

Since $\left(b+\frac{1}{2 a}\right)^{2} \geq 0$, using (1) we get
