\frac{1}{\left(a_{i}-\frac{1}{2}\right)^{2}+x^{2}}-\frac{1}{\left(a_{i}+\frac{1}{2}\right)^{2}+x^{2}} \leqslant \\
\frac{1}{\left(a_{i}-\frac{1}{2}\right)^{2}+x^{2}}-\frac{1}{\left(a_{i+1}-\frac{1}{2}\right)^{2}+x^{2}} \\
i=1,2, \cdots, n-1 \\
\end{array}
$$

Therefore,
$$
\begin{array}{l}
\sum_{i=1}^{n} \frac{a_{i}}{\left(a_{i}^{2}+x^{2}\right)^{2}} \leqslant \\
\frac{1}{2} \sum_{i=1}^{n}\left(\frac{1}{\left(a_{i}-\frac{1}{2}\right)^{2}+x^{2}}-\frac{1}{\left(a_{i+1}-\frac{1}{2}\right)^{2}+x^{2}}\right) \leqslant \\
\frac{1}{2} \cdot \frac{1}{\left(a_{1}-\frac{1}{2}\right)^{2}+x^{2}} \leqslant \frac{1}{2} \cdot \frac{1}{a_{1}\left(a_{1}-1\right)+x^{2}}
\end{array}
